import numpy as np, torch, model
net = model.load(); p=np.load('angfit.npy')
c=torch.tensor(np.load('dec_c.npy'))[:4096]; xi=torch.tensor(np.load('dec_xi.npy'))[:4096]
wr=torch.tensor(np.load('detw.npy')); br=float(np.load('detb.npy'))
def lab(a,c):
  a=np.asarray(a); ang=np.degrees(np.arctan2(a[:,1],a[:,0])); rad=np.linalg.norm(a,axis=1)
  d=(ang-np.polyval(p,np.asarray(c))+180)%360-180
  bad=(np.abs(d)<15)&(rad>2.2); off=(np.abs(((d+22.5)%45)-22.5)>15)|(rad<2.2)
  return bad,off
J=torch.tensor([[0.,-1.],[1.,0.]])
@torch.no_grad()
def dec(alpha,thr,LO,HI,sign):
  x=xi.clone()
  for k in range(20):
    t=torch.full((x.shape[0],),1-k/20)
    v,A=net.velocity(x,t,c,("out_act",),count=False)
    if alpha and LO<=k<HI:
      f=(A["out_act"]@wr+br>thr).float()[:,None]
      v=v+f*(-sign*alpha*(x@J.T))
    x=x-v/20
  return x
a0=dec(0,0,0,0,1); b0,o0=lab(a0,c); print('base',b0.mean(),o0.mean())
for sign in [1,-1]:
 for thr in [2,3]:
  for alpha in [2,4,8]:
   for LO,HI in [(4,14),(6,16)]:
    a=dec(alpha,thr,LO,HI,sign); b,o=lab(a,c); mv=(torch.norm(a-a0,dim=1)>0.3).numpy()
    print(sign,thr,alpha,LO,HI,'bad',b.mean().round(4),'off',o.mean().round(4),'moved',mv.mean().round(4),'moved nonbad',mv[~b0].mean().round(4))
